def split_refund(paid: int, used: int) -> tuple[int, int]:
    if paid < 0 or used < 0:
        raise ValueError("Paid and used amounts must be non-negative.")
    total = paid - used
    if total < 0:
        raise ValueError("Total refund amount cannot be negative.")
    half = total // 2
    return (half, total - half)
